using UnityEngine;
using UnityEditor;
using System;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.stageCamera.transform.localPosition = new Vector3(4.2f, 5.1f, -4.7f);
            s.stageCamera.transform.LookAt(s.stageCamera.transform.parent.TransformPoint(new Vector3(0, 2, 0)));
            s.stageCamera.fieldOfView = 70;
            s.OpenPage("reconstruction");
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/model-camera-review.png");
            s.Acquire("clip");
            s.OpenPage("clip");
            s.UpdateClip();
            EditorApplication.delayCall += () => ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/clip-camera-review.png");
            r.Log("Runtime only model camera candidate; clip frame0. Persist only after visual review.");
        }
    }
}

